using Astrea.BattleActions;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CorruptedConvertEffect", menuName = "Data/Battle/Effects/Enemy/CorruptedConvert Effect")]
public class CorruptedConvertEffect : Effect
{
	[Header("Battle Action List")]
	[SerializeField]
	private ConvertAction convertAction;

	[SerializeField]
	private bool convertBothPurifyAndCorrupt;

	[SerializeField]
	private bool dontConvertHexDie;

	[SerializeField]
	[ShowIf("dontConvertHexDie")]
	private DiceTier hexDieDiceTier;

	public Dice ConvertCorruptPurifyIntoOppositeAction(Dice dice)
	{
		if (dontConvertHexDie && dice.DiceTier == hexDieDiceTier)
		{
			return dice;
		}
		for (int i = 0; i < dice.GetDiceFaces().Length; i++)
		{
			BattleAction battleAction = dice.GetDiceFaces()[i].BattleAction;
			if (battleAction is PurifyAction)
			{
				battleAction = convertAction.GetConvertedBattleActionReverse(battleAction);
			}
			else if (battleAction is CorruptAction && convertBothPurifyAndCorrupt)
			{
				battleAction = convertAction.GetConvertedBattleAction(battleAction);
			}
			dice.GetDiceFaces()[i].BattleAction = battleAction;
			if (dice.GetDiceFaces()[i].EnableSecondAction)
			{
				BattleAction battleAction2 = dice.GetDiceFaces()[i].SecondBattleAction;
				if (battleAction2 is PurifyAction)
				{
					battleAction2 = convertAction.GetConvertedBattleActionReverse(battleAction2);
				}
				else if (battleAction2 is CorruptAction && convertBothPurifyAndCorrupt)
				{
					battleAction2 = convertAction.GetConvertedBattleAction(battleAction2);
				}
				dice.GetDiceFaces()[i].SecondBattleAction = battleAction2;
			}
		}
		return dice;
	}
}
